gKe(){return"\u0caa\u0ccd\u0cb0\u0cca\u0cab\u0cc8\u0cb2\u0ccd \u0cb8\u0cc6\u0c9f\u0caa\u0ccd \u0caa\u0ccd\u0cb0\u0cbe\u0cb0\u0c82\u0cad\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gKc(){return"\u0cb8\u0cc8\u0ca8\u0ccd \u0c87\u0ca8\u0ccd \u0cae\u0cc1\u0c82\u0ca6\u0cc1\u0cb5\u0cb0\u0cbf\u0cb8\u0cb2\u0cc1 \u0cb8\u0cbe\u0ca7\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gKb(){return"\u0cb8\u0cc8\u0ca8\u0ccd \u0c87\u0ca8\u0ccd \u0caa\u0cc2\u0cb0\u0ccd\u0ca3\u0c97\u0cca\u0cb3\u0cbf\u0cb8\u0cb2\u0cc1 \u0cb8\u0cbe\u0ca7\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gKf(){return"\u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cbf\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0cb0\u0ca6\u0ccd\u0ca6\u0cc1\u0c97\u0cca\u0cb3\u0cbf\u0cb8\u0cb2\u0cbe\u0c97\u0cbf\u0ca6\u0cc6."},
gKd(){return"\u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cbf\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0c95\u0ccb\u0ca1\u0ccd \u0c95\u0cb3\u0cc1\u0cb9\u0cbf\u0cb8\u0cb2\u0cc1 \u0cb8\u0cbe\u0ca7\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gK8(){return"\u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cbf\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0cb5\u0cbf\u0cb5\u0cb0\u0c97\u0cb3\u0cc1 \u0cb2\u0cad\u0ccd\u0caf\u0cb5\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gOd(){return"\u0cab\u0cc7\u0cb8\u0ccd \u0caf\u0cb6\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cbf \u0c95\u0ccd\u0caf\u0cbe\u0caa\u0ccd\u0c9a\u0cb0\u0ccd \u0c86\u0c97\u0cbf\u0ca6\u0cc6."},
gOf(){return"\u0cab\u0cc7\u0cb8\u0ccd \u0c87\u0cae\u0cc7\u0c9c\u0ccd \u0caa\u0ccd\u0cb0\u0cca\u0cb8\u0cc6\u0cb8\u0ccd \u0c86\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gOp(){return"\u0cb2\u0cca\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0caf\u0cb6\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cbf \u0c95\u0ccd\u0caf\u0cbe\u0caa\u0ccd\u0c9a\u0cb0\u0ccd \u0c86\u0c97\u0cbf\u0ca6\u0cc6."},
gOo(){return u.F},
gOs(){return"\u0c9f\u0cb0\u0ccd\u0cae\u0ccd\u0cb8\u0ccd \u0c85\u0c82\u0ca1\u0ccd \u0c95\u0c82\u0ca1\u0cbf\u0cb6\u0ca8\u0ccd\u0cb8\u0ccd \u0cb2\u0cbf\u0c82\u0c95\u0ccd \u0ca4\u0cc6\u0cb0\u0cc6\u0caf\u0cb2\u0cc1 \u0cb8\u0cbe\u0ca7\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gOr(){return"\u0c92\u0caa\u0ccd\u0caa\u0cc1\u0cb5 \u0cae\u0cca\u0ca6\u0cb2\u0cc1 \u0c9f\u0cb0\u0ccd\u0cae\u0ccd\u0cb8\u0ccd \u0c85\u0c82\u0ca1\u0ccd \u0c95\u0c82\u0ca1\u0cbf\u0cb6\u0ca8\u0ccd\u0cb8\u0ccd \u0cb2\u0cbf\u0c82\u0c95\u0ccd \u0c85\u0ca8\u0ccd\u0ca8\u0cc1 \u0c95\u0ca8\u0cbf\u0cb7\u0ccd\u0ca0 \u0c92\u0cae\u0ccd\u0cae\u0cc6 \u0ca4\u0cc6\u0cb0\u0cc6\u0caf\u0cbf\u0cb0\u0cbf."},
gNZ(){return"\u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cc8 \u0cae\u0cbe\u0ca1\u0cc1\u0cb5 \u0cae\u0cca\u0ca6\u0cb2\u0cc1 \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cab\u0ccb\u0ca8\u0ccd \u0cb8\u0c82\u0c96\u0ccd\u0caf\u0cc6 \u0cb8\u0cc7\u0cb0\u0cbf\u0cb8\u0cbf."},
gNY(){return"\u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cc8 \u0cae\u0cbe\u0ca1\u0cc1\u0cb5 \u0cae\u0cca\u0ca6\u0cb2\u0cc1 \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0c87\u0cae\u0cc7\u0cb2\u0ccd \u0cb5\u0cbf\u0cb3\u0cbe\u0cb8 \u0cb8\u0cc7\u0cb0\u0cbf\u0cb8\u0cbf."},
gOz(){return"\u0cab\u0ccb\u0ca8\u0ccd \u0cb8\u0c82\u0c96\u0ccd\u0caf\u0cc6 \u0caf\u0cb6\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cbf \u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cc8 \u0c86\u0c97\u0cbf\u0ca6\u0cc6."},
gOc(){return"\u0c87\u0cae\u0cc7\u0cb2\u0ccd \u0caf\u0cb6\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cbf \u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cc8 \u0c86\u0c97\u0cbf\u0ca6\u0cc6."},
gOI(){return"\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cb8\u0c82\u0cb8\u0ccd\u0ca5\u0cc6\u0caf\u0ca8\u0ccd\u0ca8\u0cc1 \u0ca8\u0cbf\u0cb0\u0ccd\u0ca7\u0cb0\u0cbf\u0cb8\u0cb2\u0cc1 \u0cb8\u0cbe\u0ca7\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0c87\u0cae\u0cc7\u0cb2\u0ccd \u0c85\u0ca8\u0ccd\u0ca8\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cc8 \u0cae\u0cbe\u0ca1\u0cbf."},
gOB(){return"\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0caa\u0ccd\u0cb0\u0cca\u0cab\u0cc8\u0cb2\u0ccd \u0cb8\u0cc7\u0cb5\u0ccd \u0c86\u0c97\u0cbf\u0ca6\u0cc6, \u0c86\u0ca6\u0cb0\u0cc6 \u0cb8\u0cc8\u0ca8\u0ccd \u0c87\u0ca8\u0ccd \u0caa\u0cc2\u0cb0\u0ccd\u0ca3\u0c97\u0cca\u0cb3\u0ccd\u0cb3\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0cb8\u0cc8\u0ca8\u0ccd \u0c87\u0ca8\u0ccd \u0cae\u0cbe\u0ca1\u0cbf."},
gOt(){return"\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cae\u0cbe\u0cb9\u0cbf\u0ca4\u0cbf \u0c85\u0caa\u0ccd\u200c\u0ca1\u0cc7\u0c9f\u0ccd \u0c86\u0c97\u0cbf\u0ca6\u0cc6. \u0c96\u0cbe\u0ca4\u0cc6 \u0cb8\u0c95\u0ccd\u0cb0\u0cbf\u0caf\u0c97\u0cca\u0cb3\u0cbf\u0cb8\u0cb2\u0cc1 \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ccd\u0caf\u0cbe\u0ca8\u0cc7\u0c9c\u0cb0\u0ccd \u0c85\u0caa\u0ccd\u0cb0\u0cc2\u0cb5\u0cb2\u0ccd\u200c\u0c97\u0cbe\u0c97\u0cbf \u0c95\u0cbe\u0caf\u0cbf\u0cb0\u0cbf."},
gOx(){return"\u0cab\u0ccb\u0ca8\u0ccd \u0cb8\u0c82\u0c96\u0ccd\u0caf\u0cc6 \u0c85\u0c97\u0ca4\u0ccd\u0caf."},
gOy(){return"\u0cab\u0ccb\u0ca8\u0ccd \u0cb8\u0c82\u0c96\u0ccd\u0caf\u0cc6 \u0c95\u0ca8\u0cbf\u0cb7\u0ccd\u0ca0 10 \u0c85\u0c82\u0c95\u0cbf\u0c97\u0cb3\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1."},
gOj(){return"\u0caa\u0cc2\u0cb0\u0ccd\u0ca3 \u0cb9\u0cc6\u0cb8\u0cb0\u0cc1 \u0c85\u0c97\u0ca4\u0ccd\u0caf."},
gOk(){return"\u0caa\u0cc2\u0cb0\u0ccd\u0ca3 \u0cb9\u0cc6\u0cb8\u0cb0\u0cc1 \u0c95\u0ca8\u0cbf\u0cb7\u0ccd\u0ca0 2 \u0c85\u0c95\u0ccd\u0cb7\u0cb0\u0c97\u0cb3\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1."},
gOb(){return"\u0c87\u0cae\u0cc7\u0cb2\u0ccd \u0c85\u0c97\u0ca4\u0ccd\u0caf."},
