gO9(){return"\u0c9c\u0ca8\u0ccd\u0cae \u0ca6\u0cbf\u0ca8\u0cbe\u0c82\u0c95 \u0c85\u0c97\u0ca4\u0ccd\u0caf."},
gOq(){return"\u0cb2\u0cca\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0c85\u0c97\u0ca4\u0ccd\u0caf."},
gOg(){return"\u0cb0\u0cbf\u0c9c\u0cbf\u0cb8\u0ccd\u0c9f\u0ccd\u0cb0\u0cc7\u0cb6\u0ca8\u0ccd \u0caa\u0cc2\u0cb0\u0ccd\u0ca3\u0c97\u0cca\u0cb3\u0cbf\u0cb8\u0cb2\u0cc1 \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cae\u0cc1\u0c96\u0cb5\u0ca8\u0ccd\u0ca8\u0cc1 \u0c95\u0ccd\u0caf\u0cbe\u0caa\u0ccd\u0c9a\u0cb0\u0ccd \u0cae\u0cbe\u0ca1\u0cbf."},
